// Generated by nocgen for tiny.
// Behavioural stand-in for the NoC: decodes each master request, waits the
// shortest-path request latency, hands it to the target slave port (one
// transaction at a time per slave, so contention queues up), then waits the
// response latency. It lets the testbench run before the real mesh exists;
// replace it with your RTL in tb_top.sv. Not synthesisable.
module noc_mesh_stub
  import noc_params_pkg::*;
(
  input logic clk,
  input logic rst_n,
  axi_if      m_if [NUM_MASTERS],   // NoC master ports (TB drives these)
  axi_if      s_if [NUM_SLAVES]     // NoC slave ports  (TB answers on these)
);

  typedef struct {
    bit       is_write;
    int       src;
    id_t      id;
    addr_t    addr;
    bit [7:0] len;
    data_t    wdata[$];
    strb_t    wstrb[$];
  } req_t;

  typedef struct {
    bit [1:0] resp;
    data_t    rdata[$];
  } rsp_t;

  mailbox #(req_t) to_slave  [NUM_SLAVES];
  mailbox #(rsp_t) to_master [NUM_MASTERS];

  initial begin
    foreach (to_slave[i])  to_slave[i]  = new();
    foreach (to_master[i]) to_master[i] = new();
  end

  // ---- master-side network interfaces --------------------------------------
  for (genvar i = 0; i < NUM_MASTERS; i++) begin : g_mni
    initial begin
      m_if[i].awready <= 0; m_if[i].wready <= 0; m_if[i].bvalid <= 0;
      m_if[i].arready <= 0; m_if[i].rvalid <= 0; m_if[i].rlast <= 0;
      m_if[i].bid <= '0; m_if[i].bresp <= '0; m_if[i].rid <= '0; m_if[i].rdata <= '0; m_if[i].rresp <= '0;
      @(posedge rst_n);
      forever begin
        req_t rq;
        rsp_t rs;
        int   s;
        // Accept one request (reads first if both are pending).
        do @(posedge clk); while (!(m_if[i].arvalid || m_if[i].awvalid));
        rq.wdata.delete(); rq.wstrb.delete();
        if (m_if[i].arvalid) begin
          rq.is_write = 0; rq.id = m_if[i].arid; rq.addr = m_if[i].araddr; rq.len = m_if[i].arlen;
          m_if[i].arready <= 1;
          @(posedge clk);
          m_if[i].arready <= 0;
        end else begin
          rq.is_write = 1; rq.id = m_if[i].awid; rq.addr = m_if[i].awaddr; rq.len = m_if[i].awlen;
          m_if[i].awready <= 1;
          @(posedge clk);
          m_if[i].awready <= 0;
          m_if[i].wready  <= 1;
          for (int b = 0; b <= rq.len; b++) begin
            do @(posedge clk); while (!m_if[i].wvalid);
            rq.wdata.push_back(m_if[i].wdata);
            rq.wstrb.push_back(m_if[i].wstrb);
          end
          m_if[i].wready <= 0;
        end
        rq.src = i;
        s = decode(rq.addr);
        if (s < 0) begin
          rs.resp = 2'b11;  // DECERR
          rs.rdata.delete();
          for (int b = 0; b <= rq.len; b++) rs.rdata.push_back('0);
        end else begin
          repeat (REQ_LAT[i][s] - 1) @(posedge clk);
          to_slave[s].put(rq);
          to_master[i].get(rs);
          repeat (RSP_LAT[i][s] - 1) @(posedge clk);
        end
        if (rq.is_write) begin
          m_if[i].bvalid <= 1; m_if[i].bid <= rq.id; m_if[i].bresp <= rs.resp;
          do @(posedge clk); while (!m_if[i].bready);
          m_if[i].bvalid <= 0;
        end else begin
          for (int b = 0; b <= rq.len; b++) begin
            m_if[i].rvalid <= 1; m_if[i].rid <= rq.id; m_if[i].rresp <= rs.resp;
            m_if[i].rdata <= rs.rdata[b]; m_if[i].rlast <= (b == rq.len);
            do @(posedge clk); while (!m_if[i].rready);
          end
          m_if[i].rvalid <= 0; m_if[i].rlast <= 0;
        end
      end
    end
  end

  // ---- slave-side network interfaces ---------------------------------------
  for (genvar j = 0; j < NUM_SLAVES; j++) begin : g_sni
    initial begin
      s_if[j].awvalid <= 0; s_if[j].wvalid <= 0; s_if[j].bready <= 0;
      s_if[j].arvalid <= 0; s_if[j].rready <= 0; s_if[j].wlast <= 0;
      s_if[j].awid <= '0; s_if[j].awaddr <= '0; s_if[j].awlen <= '0; s_if[j].awsize <= '0; s_if[j].awburst <= '0;
      s_if[j].arid <= '0; s_if[j].araddr <= '0; s_if[j].arlen <= '0; s_if[j].arsize <= '0; s_if[j].arburst <= '0;
      s_if[j].wdata <= '0; s_if[j].wstrb <= '0;
      @(posedge rst_n);
      forever begin
        req_t rq;
        rsp_t rs;
        to_slave[j].get(rq);
        rs.rdata.delete();
        if (rq.is_write) begin
          s_if[j].awid <= rq.id; s_if[j].awaddr <= rq.addr; s_if[j].awlen <= rq.len;
          s_if[j].awsize <= AXI_SIZE; s_if[j].awburst <= 2'b01; s_if[j].awvalid <= 1;
          do @(posedge clk); while (!s_if[j].awready);
          s_if[j].awvalid <= 0;
          for (int b = 0; b <= rq.len; b++) begin
            s_if[j].wdata <= rq.wdata[b]; s_if[j].wstrb <= rq.wstrb[b];
            s_if[j].wlast <= (b == rq.len); s_if[j].wvalid <= 1;
            do @(posedge clk); while (!s_if[j].wready);
          end
          s_if[j].wvalid <= 0; s_if[j].wlast <= 0;
          s_if[j].bready <= 1;
          do @(posedge clk); while (!s_if[j].bvalid);
          rs.resp = s_if[j].bresp;
          s_if[j].bready <= 0;
        end else begin
          s_if[j].arid <= rq.id; s_if[j].araddr <= rq.addr; s_if[j].arlen <= rq.len;
          s_if[j].arsize <= AXI_SIZE; s_if[j].arburst <= 2'b01; s_if[j].arvalid <= 1;
          do @(posedge clk); while (!s_if[j].arready);
          s_if[j].arvalid <= 0;
          s_if[j].rready <= 1;
          for (int b = 0; b <= rq.len; b++) begin
            do @(posedge clk); while (!s_if[j].rvalid);
            rs.rdata.push_back(s_if[j].rdata);
            rs.resp = s_if[j].rresp;
          end
          s_if[j].rready <= 0;
        end
        to_master[rq.src].put(rs);
      end
    end
  end

endmodule
